{
  "tool": "run_shell",
  "args": {
    "cmd": "pip install sktime && python -c \"import pandas as pd; import numpy as np; from sktime.transformations.panel.rocket import Rocket; from sklearn.linear_model import RidgeClassifierCV; from sklearn.metrics import balanced_accuracy_score; train = pd.read_csv('data/train.csv'); val = pd.read_csv('data/val.csv'); char_map = {'*': 0, '.': 1, 'u': 2, 'v': 3, 'w': 4, 'x': 5, 'y': 6, 'z': 7}; X_train = np.array([[char_map[c] for c in s] for s in train['symbol_series']]); X_val = np.array([[char_map[c] for c in s] for s in val['symbol_series']]); rocket = Rocket(random_state=42); rocket.fit(X_train); X_train_transform = rocket.transform(X_train); X_val_transform = rocket.transform(X_val); classifier = RidgeClassifierCV(alphas=np.logspace(-3, 3, 10)); classifier.fit(X_train_transform, train['label']); y_pred = classifier.predict(X_val_transform); print(f'ROCKET Val Balanced Acc: {balanced_accuracy_score(val[\\\"label\\\"], y_pred):.4f}')\""
  }
}
